// AUD-02: audit trails from another tenant are invisible.
// Assumption: a Globex Procurement user exists in the seed data as "buyer@globex.test".
// Adjust GLOBEX_EMAIL if the seed uses a different address.
import { API_URL, PASSWORD, expect, expectStatus, test, uniqueName } from "../../fixtures";

const GLOBEX_EMAIL = "buyer@globex.test";

test.describe("AUD-02 vendor audit trail", () => {
  test(
    "Audit trails from another tenant are invisible",
    { tag: "@AUD-02" },
    async ({ apiAs, request }) => {
      // Arrange: a Northwind member signs in through the shared apiAs fixture.
      const member = await apiAs("member");

      // Arrange: a Globex user creates a vendor in the other tenant.
      const loginResponse = await request.post(`${API_URL}/api/auth/login`, {
        data: { email: GLOBEX_EMAIL, password: PASSWORD },
      });
      const { access_token: globexToken } = await expectStatus<{ access_token: string }>(loginResponse, 200);
      const globexAuth = { Authorization: `Bearer ${globexToken}` };

      const createResponse = await request.post(`${API_URL}/api/vendors`, {
        headers: globexAuth,
        data: {
          name: uniqueName("AUD-02 Globex Vendor"),
          category: "software",
          contact_email: "ap@globex-vendor.test",
        },
      });
      const vendor = await expectStatus<{ id: string }>(createResponse, 201);
      expect(vendor.id).toBeTruthy();

      // Act: the Northwind member requests the Globex vendor's audit trail.
      const response = await member.get(`/api/vendors/${vendor.id}/audit`);

      // Assert: the other tenant's vendor is not visible.
      expect(response.status()).toBe(404);
    },
  );
});
